        { ns = 'events', label = 'present', sig = 'present', desc = 'runs once a frame, from the game\'s Present, after your tasks. Draw ImGui windows here, and read anything that changes frame to frame. Nothing is passed; vana.tasks.frame() counts the frames.', page = '02-events.md', live = {}, find = { 'on(\'present\'' }, event = 'present', more = { { 'Handler gets', 'nothing' } } },
        { ns = 'events', label = 'command', sig = 'command', desc = 'every command line the game is about to run, typed or sent by an addon. e.mode is the chat mode it was typed in (1 for the chat box); e.injected is true for a line VanaCore or an addon ran (vana.chat.run, a script, a bind). VanaCore\'s own commands (/addon, /vana, /bind) are taken before addons see them. Plugins with a negative priority see lines before addons; the rest after.', page = '02-events.md', live = {}, find = { 'on(\'command\'' }, event = 'command', more = { { 'e', 'command (the line), mode, injected, blocked' }, { 'Return true', 'The game doesn\'t run the line' } } },
        { ns = 'events', label = 'unhandled', sig = 'unhandled', desc = 'a //something line no addon or plugin took. Return true to claim it, else the chat log says Unknown command.', page = '02-events.md', live = {}, find = { 'on(\'unhandled\'' }, event = 'unhandled', more = { { 'e', 'command (a // line nothing took, without the //)' }, { 'Return true', 'Taken: no "Unknown command"' } } },
        { ns = 'events', label = 'text_in', sig = 'text_in', desc = 'a line coming into the chat log, after plugins. Change e.message_modified (and e.mode_modified, e.indent_modified) to change what\'s shown. The text is Shift-JIS with the game\'s own control codes in it. e.mode is the game\'s three mode bytes (mode | flags << 8 | ... << 16); the chat mode itself is bit.band(e.mode, 0xFF). A line your own addon prints doesn\'t come back to your text_in, but does reach other addons\'.', page = '02-events.md', live = {}, find = { 'on(\'text_in\'' }, event = 'text_in', more = { { 'e', 'mode, mode_modified, indent, indent_modified, message, message_modified, injected, blocked' }, { 'Return true', 'The line isn\'t shown' } } },
        { ns = 'events', label = 'text_out', sig = 'text_out', desc = 'a line the player typed that isn\'t a command, on its way to the game as chat.', page = '02-events.md', live = {}, find = { 'on(\'text_out\'' }, event = 'text_out', more = { { 'e', 'mode, mode_modified, message, message_modified, injected, blocked' }, { 'Return true', 'The line doesn\'t go to the game' } } },
        { ns = 'events', label = 'login', sig = 'login', desc = '', page = '02-events.md', live = {}, find = { 'on(\'login\'' }, event = 'login', more = { { 'When', 'A character is in the world' }, { 'e', 'name, id, zone' } } },
        { ns = 'events', label = 'logout', sig = 'logout', desc = '', page = '02-events.md', live = {}, find = { 'on(\'logout\'' }, event = 'logout', more = { { 'When', 'Back at the title screen or character select (or another character logged in)' }, { 'e', 'name' } } },
        { ns = 'events', label = 'zone_out', sig = 'zone_out', desc = '', page = '02-events.md', live = {}, find = { 'on(\'zone_out\'' }, event = 'zone_out', more = { { 'When', 'The server sent the character out of its zone' }, { 'e', 'zone (the one being left)' } } },
        { ns = 'events', label = 'zone_change', sig = 'zone_change', desc = '', page = '02-events.md', live = {}, find = { 'on(\'zone_change\'' }, event = 'zone_change', more = { { 'When', 'The server put the character in a zone: every zone-in after login, Mog House in and out too (the zone can be the same)' }, { 'e', 'zone, previous' } } },
        { ns = 'events', label = 'job_change', sig = 'job_change', desc = '', page = '02-events.md', live = {}, find = { 'on(\'job_change\'' }, event = 'job_change', more = { { 'When', 'The main job changed' }, { 'e', 'job, job_name, level, previous, previous_name, previous_level' } } },
        { ns = 'events', label = 'subjob_change', sig = 'subjob_change', desc = '', page = '02-events.md', live = {}, find = { 'on(\'subjob_change\'' }, event = 'subjob_change', more = { { 'When', 'The support job changed (0 and "" for none)' }, { 'e', 'the same' } } },
        { ns = 'events', label = 'level_change', sig = 'level_change', desc = '', page = '02-events.md', live = {}, find = { 'on(\'level_change\'' }, event = 'level_change', more = { { 'When', 'The main job\'s level changed, the job the same (level sync too)' }, { 'e', 'job, job_name, level, previous_level' } } },
        { ns = 'events', label = 'target_change', sig = 'target_change', desc = '', page = '02-events.md', live = {}, find = { 'on(\'target_change\'' }, event = 'target_change', more = { { 'When', 'The main target changed (index 0: none)' }, { 'e', 'index, id, previous_index, previous_id' } } },
