        { ns = 'events', label = 'action_menu_open, action_menu_close', sig = 'action_menu_open, action_menu_close', desc = '', page = '02-events.md', live = {}, find = { 'on(\'action_menu_open\'', 'on(\'action_menu_close\'' }, event = 'action_menu_open', more = { { 'When', 'The action menu (Attack, Magic, ...)' } } },
