        { ns = 'events', label = 'packet_in', sig = 'packet_in', desc = '', page = '02-events.md', live = {}, find = { 'on(\'packet_in\'' }, event = 'packet_in', more = { { 'e', 'id, size, data, data_raw, data_modified, data_modified_raw, chunk_size, chunk_data, chunk_data_raw, injected, blocked' }, { 'Return true', 'The game doesn\'t get it' } } },
