        { ns = 'events', label = 'key', sig = 'key', desc = 'the game window\'s key messages: wparam the virtual-key code, lparam Windows\' (bit 31 set for a release, bit 30 for a repeat). While the chat line is open, Ashita and Windower addons don\'t get presses; VanaCore addons do.', page = '02-events.md', live = {}, find = { 'on(\'key\'' }, event = 'key', more = { { 'Handler gets', 'wparam, lparam, blocked (not a table)' }, { 'Return true', 'The game\'s window doesn\'t get the key' } } },
        { ns = 'events', label = 'mouse', sig = 'mouse', desc = 'type is the Windows message less 0x200: 0 move, 1 left down, 2 left up, 4 right down, 5 right up, 7 middle down, 8 middle up, 10 wheel. x, y in VanaCore\'s interface pixels (vana.ui.screen()\'s), delta the wheel\'s turn (120 a notch), modifiers the keys held: 1 Shift, 2 Ctrl, 4 Alt. A press or wheel over an ImGui window is ImGui\'s: you hear it with blocked true.', page = '02-events.md', live = {}, find = { 'on(\'mouse\'' }, event = 'mouse', more = { { 'Handler gets', 'type, x, y, delta, blocked, modifiers (not a table)' }, { 'Return true', 'The game doesn\'t get the mouse message' } } },
        { ns = 'events', label = 'key_state', sig = 'key_state', desc = 'each read of the game\'s DirectInput keyboard: e.data the 256 key states (DirectInput key codes, 0x80 set while down). Write through e.data_raw with the FFI to make the game see a key.', page = '02-events.md', live = {}, find = { 'on(\'key_state\'' }, event = 'key_state', more = { { 'Handler gets', 'e.data (256 bytes), e.data_raw, e.size' } } },
        { ns = 'events', label = 'key_data', sig = 'key_data', desc = 'each buffered DirectInput key event: e.key the DIK code.', page = '02-events.md', live = {}, find = { 'on(\'key_data\'' }, event = 'key_data', more = { { 'Handler gets', 'e.key, e.down, e.injected, e.blocked' }, { 'Return true', 'The game doesn\'t get the key' } } },
